// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(address log1, address log2) public {
        vm.assume(log1 != log2);
        vm.assume(log1 != address(0));
        vm.assume(log2 != address(0));
        vm.assume(log1.code.length == 0 && log2.code.length == 0);

        c.SetMinSum(0);
        c.SetLogFile(log1);
        c.Initialized();

        bool ok;
        try c.SetLogFile(log2) { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }
}
